R=C=10
# flood-fill region of 8 connected to 6 by 4-neighbor
from collections import deque
q=deque([(9,9)]); reach={(9,9)}
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  p=(r+dr,c+dc)
  if 0<=p[0]<R and 0<=p[1]<C and p not in reach and g[p[0]][p[1]]==8:
   reach.add(p); q.append(p)
# all 1 components are boundary-connected in this test; mark accessible 8 at boundary or 8-neighbor of a 1
out=[row[:] for row in g]
for r,c in reach:
 if r in (0,R-1) or c in (0,C-1) or any(0<=r+dr<R and 0<=c+dc<C and g[r+dr][c+dc]==1 for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0)):
  out[r][c]=7
