def proc(g):
 R,C=len(g),len(g[0]); q=deque(); reach=set()
 for r in range(R):
  for c in range(C):
   if g[r][c]==6: q.append((r,c));reach.add((r,c))
 while q:
  r,c=q.popleft()
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and g[rr][cc]==8 and (rr,cc) not in reach:
    reach.add((rr,cc));q.append((rr,cc))
 # 1 components via 4-neighbor; eligible if border
 ones={(r,c) for r in range(R) for c in range(C) if g[r][c]==1}; eligible=set()
 while ones:
  s=ones.pop(); comp={s}; q2=[s]
  while q2:
   r,c=q2.pop()
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    p=(r+dr,c+dc)
    if p in ones:
     ones.remove(p); comp.add(p);q2.append(p)
  if any(r==0 or c==0 or r==R-1 or c==C-1 for r,c in comp): eligible |= comp
 out=[row[:] for row in g]
 for r,c in reach:
  near= any(0<=r+dr<R and 0<=c+dc<C and (r+dr,c+dc) in eligible for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0))
  if r==0 or c==0 or r==R-1 or c==C-1 or near:out[r][c]=7
 return out
